from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
html=(root/'commerce/admin/admin.html').read_text();css=(root/'commerce/admin/admin.css').read_text();js=(root/'commerce/admin/admin.mjs').read_text()
html=html.replace('<link rel="stylesheet" href="/admin/admin.css">','<style>'+css+'</style>').replace('<script src="/admin/admin.mjs" type="module"></script>','')
html=html.replace('Order desk · test mode','Order desk · sample data only').replace('<section id="login">','<section id="login" hidden>').replace('<section id="desk" hidden>','<section id="desk">')
html=html.replace('Test orders only. Email delivery is not connected; notifications shown here have not been sent.','LOCAL DEMONSTRATION · All orders and customers below are fictional. Changes reset when you reload. No payment, email or stock change leaves this page.')
start=js.index('async function api(');end=js.index('\nfunction text(',start)
samples=[{'id':'11111111-1111-4111-8111-111111111111','status':'paid','region':'eu','quantity':1,'total_cents':4400,'refunded_cents':0,'tracking':None,'version':1,'created_at':'2026-11-17T10:00:00Z','customer_email':'sample.reader@example.invalid','delivery':{'name':'Sample Reader','address':{'country':'ES'}},'audit':[{'created_at':'2026-11-17T10:00:00Z','action':'sample_payment_verified'}]}, {'id':'22222222-2222-4222-8222-222222222222','status':'packing','region':'uk','quantity':1,'total_cents':4800,'refunded_cents':0,'tracking':None,'version':2,'created_at':'2026-11-17T09:30:00Z','customer_email':'sample.gift@example.invalid','delivery':{'name':'Sample Gift Recipient','address':{'country':'GB'}},'audit':[{'created_at':'2026-11-17T09:30:00Z','action':'sample_packing'}]}, {'id':'33333333-3333-4333-8333-333333333333','status':'pending','region':'eu','quantity':1,'total_cents':4400,'refunded_cents':0,'tracking':None,'version':0,'created_at':'2026-11-17T11:00:00Z','customer_email':None,'delivery':None,'audit':[]}]
mock='''const sampleOrders='''+json.dumps(samples)+''';let sampleStock=12,notifications=2;
async function api(path,options={}){if(path==='orders')return{orders:structuredClone(sampleOrders),available:sampleStock,pendingNotifications:notifications};if(path==='inventory'){const input=JSON.parse(options.body);if(!Number.isInteger(input.adjustment)||!input.reason.trim()||sampleStock+input.adjustment<0)throw new Error('Enter a valid stock adjustment and reason.');sampleStock+=input.adjustment;return{available:sampleStock};}const row=sampleOrders.find(o=>o.id===path.split('/')[1]);if(!row)throw new Error('Sample order not found.');if(options.method==='PATCH'){const input=JSON.parse(options.body);if(Number(options.headers['If-Match'])!==row.version)throw new Error('Refresh before updating.');if(({paid:'packing',packing:'dispatched'})[row.status]!==input.status)throw new Error('That next step is unavailable.');row.status=input.status;row.tracking=input.tracking;row.version++;row.audit.push({created_at:new Date().toISOString(),action:'sample_'+input.status});if(input.status==='dispatched')notifications++;return{order:structuredClone(row)};}return{order:structuredClone(row),audit:structuredClone(row.audit)};}
'''
js=js[:start]+mock+js[end:]+"\nrefresh();"
html=html.replace('</body>','<script type="module">'+js+'</script></body>')
(root.parent/'I_Will_Bloom_Order_Desk_Preview.html').write_text(html)
print('Exported a self-contained order desk demonstration with fictional data.')
